void check_native_replay() {
  NativeOracleFixture fixture;
  const std::vector<double> a{4.0 / 3.0, 4.0 / 3.0}, b{0, 0}, y{-1.0 / 3.0, -1.0 / 3.0};
  auto& oracle = *fixture.oracle;
  require(oracle.evaluate(fixture.reduced, a, y, 2) == candidate::OracleDecision::accept && oracle.candidate,
      "同一非空恢复栈的首个A点须通过原模型终验");
  const auto owned_a = *oracle.candidate;
  require(oracle.evaluate(fixture.reduced, b, y, 3) == candidate::OracleDecision::reject && oracle.candidate &&
      oracle.candidate->x != owned_a.x && !quality_ok(oracle.candidate->checked),
      "同一Highs实例第二次B恢复须实际改变原坐标点并保真实拒绝质量");
  require(same_vector(owned_a.x, {3, a[0], a[1]}) && quality_ok(owned_a.checked),
      "首个A拥有的向量不能被原生解缓存的后续恢复覆盖");
  require(oracle.evaluate(fixture.reduced, a, y, 4) == candidate::OracleDecision::accept && oracle.candidate &&
      same_vector(oracle.candidate->x, owned_a.x) && same_vector(oracle.candidate->y, owned_a.y) &&
      same_verification(oracle.candidate->checked.primal, owned_a.checked.primal) &&
      same_optimality(oracle.candidate->checked.optimality, owned_a.checked.optimality),
      "同一presolve栈A→B→A须恢复相同数值与完整原质量，不能复用末次缓存冒充");
  require(fixture.stats.oracle.events.size() == 3 && fixture.stats.oracle.started == 3 && fixture.stats.oracle.completed == 3 &&
      fixture.stats.oracle.accepted == 2 && fixture.stats.oracle.rejected == 1 &&
      fixture.stats.postsolve.completed == 3 && fixture.stats.assessments.completed == 3 &&
      fixture.stats.oracle.candidate_event == 2 && !fixture.stats.oracle.selected_event,
      "非空重放须实际发生三次恢复和原验，局部候选不等于owner已提交");
  fixture.no_native_iterations();
  ++transaction_cases;
  details.push_back({"native_postsolve_replays_A_B_A_without_lp", "transaction"});
}

void check_oracle_failure(bool exception) {
  NativeOracleFixture fixture;
  fixture.error_after_assessment = exception;
  fixture.expire_after_assessment = !exception;
  const std::vector<double> x{4.0 / 3.0, 4.0 / 3.0}, y{-1.0 / 3.0, -1.0 / 3.0};
  const auto decision = fixture.oracle->evaluate(fixture.reduced, x, y, 11);
  const auto expected = exception ? candidate::OracleDecision::error : candidate::OracleDecision::budget;
  require(fixture.injected && decision == expected && fixture.oracle->terminal == expected &&
      !fixture.oracle->candidate && fixture.oracle->current_frame == nullptr &&
      fixture.stats.oracle.started == 1 && fixture.stats.oracle.completed == 1 && fixture.stats.oracle.events.size() == 1,
      "oracle内部预算与异常须不抛穿assess，保终止类型并释放局部frame引用");
  const auto& event = fixture.stats.oracle.events.front();
  require(event.postsolve.started == 1 && event.postsolve.completed == 1 && event.assessments.started == 1 &&
      event.assessments.completed == 1 && event.original_quality && event.original_quality->numerically_optimal &&
      event.budget.checks > 0 && event.budget.loop_units > 0 && event.timings.recovery > 0 && event.timings.verification > 0 &&
      fixture.stats.assessments.completed == 1 && !fixture.stats.oracle.selected_event && !fixture.stats.accepted &&
      std::string(event.decision) == (exception ? "error" : "budget") &&
      (exception ? fixture.stats.oracle.errors : fixture.stats.oracle.budget_failures) == 1,
      "原验已完成后失败可留诊断质量，但不得丢已付工作或伪造owner提交");
  fixture.no_native_iterations();
  if (exception) { ++exception_cases; details.push_back({"oracle_error_preserves_event_work", "exception"}); }
  else { ++budget_cases; details.push_back({"oracle_budget_preserves_event_work", "budget"}); }
}

void check_real_core_oracle_failure(bool exception) {
  NativeOracleFixture fixture;
  fixture.error_after_assessment = exception;
  fixture.expire_after_assessment = !exception;
  solver::SolveResult result;
  {
    candidate::ScopedOracle scope(&*fixture.oracle);
    ++component_ipm_calls;
    // 真实HSD迭代与factor均执行；仅oracle的Now在原验完成后注入确定性失败。
    // core自身继续使用同一个真实Clock epoch，不伪造求解计时或更换公开预算。
    result = solver::v91_core(fixture.reduced, fixture.options, fixture.start);
  }
  const auto expected = exception ? candidate::OracleDecision::error : candidate::OracleDecision::budget;
  require(fixture.injected && result.status == (exception ? "numerical_error" : "time_limit") &&
      result.backend_status == result.status && fixture.oracle->terminal == expected &&
      result.ipm_iterations && *result.ipm_iterations > 0 && result.ipm_factorizations && *result.ipm_factorizations > 0 &&
      fixture.stats.oracle.started == 1 && fixture.stats.oracle.completed == 1 && fixture.stats.oracle.events.size() == 1,
      "真实assess的budget/error桥接必须由实际HSD core返回既有失败类型，并保已付迭代与factor");
  const auto& event = fixture.stats.oracle.events.front();
  require(event.iteration == result.ipm_iterations && event.postsolve.completed == 1 &&
      event.assessments.completed == 1 && event.original_quality && event.budget.checks > 0 &&
      event.budget.loop_units > 0 && event.timings.recovery > 0 && event.timings.verification > 0 &&
      !fixture.oracle->candidate && !fixture.stats.oracle.selected_event && !fixture.stats.accepted &&
      (exception ? fixture.stats.oracle.errors : fixture.stats.oracle.budget_failures) == 1,
      "真实core异常收口不能抹去oracle事件的恢复、原验与部分成本，也不得提交原候选");
  require(result.solve_seconds >= 0 && result.verification_seconds >= 0 && result.total_seconds >= result.solve_seconds,
      "真实core保自身时钟测量，不把oracle合成时钟写成其耗时证据");
  fixture.no_native_iterations();
  if (exception) { ++exception_cases; details.push_back({"oracle_real_core_error_bridge", "exception"}); }
  else { ++budget_cases; details.push_back({"oracle_real_core_budget_bridge", "budget"}); }
}

struct WarmMode {
  explicit WarmMode(bool enabled) : previous(warm_state::enabled_override) { warm_state::enabled_override = enabled; }
  ~WarmMode() { warm_state::enabled_override = previous; }
  std::optional<bool> previous;
};

struct WarmConeSeed {
  solver::ConeModel cone;
  solver::Point point;
  double tau = 2, kappa = 3;
};

WarmConeSeed warm_cone_seed(const solver::Model& model, const solver::SolveOptions& options,
    solver::Clock::time_point start, bool optimal = true) {
  require(model.costs.size() == 2 && model.row_lower.size() == 2, "本组件种子仅用于已声明的二变量解析夹具");
  WarmConeSeed seed;
  seed.cone = solver::canonicalize(model, options, start);
  const std::vector<double> physical_x(2, optimal ? 4.0 / 3.0 : 0), physical_y(2, -1.0 / 3.0);
  seed.point.x.resize(seed.cone.costs.size());
  seed.point.z.assign(seed.cone.rhs.size(), 0);
  seed.point.s.assign(seed.cone.rhs.size(), 0);
  for (std::size_t col = 0; col < seed.point.x.size(); ++col) {
    const auto original = seed.cone.original_columns.empty() ? col : seed.cone.original_columns[col];
    seed.point.x[col] = static_cast<double>(static_cast<long double>(physical_x[original]) /
        seed.cone.column_scale[col] * seed.tau);
    require(std::isfinite(seed.point.x[col]), "同Cone种子变量须有限");
  }
  for (std::size_t row = 0; row < seed.point.z.size(); ++row) {
    if (seed.cone.original_row[row] < 0) continue;
    const auto original = static_cast<std::size_t>(seed.cone.original_row[row]);
    const long double scale = static_cast<long double>(seed.cone.dual_sign[row]) * seed.cone.row_scale[row] * seed.cone.objective_scale;
    require(scale != 0 && std::isfinite(scale), "同Cone行乘子映射尺度须有效");
    seed.point.z[row] = static_cast<double>(static_cast<long double>(physical_y[original]) / scale * seed.tau);
    require(std::isfinite(seed.point.z[row]) && (!seed.cone.inequality[row] || seed.point.z[row] >= 0),
        "种子必须在同Cone坐标，不把恢复后的模型行对偶直接当作Cone乘子");
  }
  return seed;
}

solver::SolveResult warm_failure(const solver::Model& model) {
  auto result = bait(model, "numerical_error");
  candidate::clear_coordinate_quality(result);
  result.verification_seconds = 0;
  result.message = "组件保留的原KKT错误";
  return result;
}

void check_warm_reduced_original_oracle() {
  Mode quiet(true);
  NativeOracleFixture fixture;
  const auto seed = warm_cone_seed(fixture.reduced, fixture.options, fixture.start);
  auto result = warm_failure(fixture.reduced);
  warm_state::Log log;
  log.enabled = true;
  warm_kernel::Limits limits;
  limits.max_iterations = 0;
  int checks = 0;
  const warm_kernel::Budget budget = [&] { ++checks; solver::check_budget(fixture.options, fixture.start); };
  bool accepted = false;
  {
    candidate::ScopedOracle oracle(&*fixture.oracle);
    accepted = solver::v91_run_warm(seed.cone, seed.point, seed.tau, seed.kappa, fixture.options,
        fixture.start, result, log, limits, budget);
  }
  require(accepted && log.attempted && log.accepted && std::string(log.status) == "accepted" && log.kernel.accepted &&
      log.kernel.stats.seed_available && log.kernel.stats.steps_started == 0 && log.kernel.stats.steps_completed == 0 &&
      log.kernel.stats.assessments_started == 1 && log.kernel.stats.assessments_completed == 1 && checks > 0,
      "完整同Cone种子应在step0独立验收，不依赖last完整assess摘要或伪造PDHG迭代");
  original_quality(fixture.reduced, result, 88.0 / 3.0);
  legacy_bait(result);
  require(fixture.stats.oracle.started == 1 && fixture.stats.oracle.completed == 1 && fixture.stats.oracle.accepted == 1 &&
      fixture.stats.postsolve.completed == 1 && fixture.stats.assessments.completed == 1 && fixture.oracle->candidate &&
      quality_ok(fixture.oracle->candidate->checked) && fixture.oracle->candidate->x.size() == 3 &&
      fixture.stats.oracle.events.front().iteration == 137 && !fixture.stats.oracle.selected_event &&
      log.seed_quality && log.seed_quality->completed_steps == 0 && log.seed_quality->numerically_optimal == true,
      "local assess必须隔离原oracle，随后只咨询一次trial模型坐标；原候选由父owner拥有，暖提交不冒充父提交");
  require(fixture.oracle->candidate->x[0] == 3 && same_model(result.model, fixture.reduced),
      "原坐标恢复必须保固定列，而child只持约化模型坐标");
  fixture.no_native_iterations();
  ++transaction_cases;
  details.push_back({"warm_reduced_original_oracle", "transaction"});
}

void check_warm_oracle_capacity() {
  Mode quiet(true);
  auto original = coupled(true);
  original.costs[0] = 8.0 / 9.0;
  NativeOracleFixture fixture(original);
  const std::vector<double> near(2, 4.0 / 3.0 - 5.06e-8), dual(2, -1.0 / 3.0);
  require(quality_ok(solver::verify_lp_solution(fixture.reduced, near, dual)), "容量夹具应确有可触发原验的局部点");
  for (int event = 0; event < 204; ++event) {
    require(fixture.oracle->evaluate(fixture.reduced, near, dual, 137) == candidate::OracleDecision::reject,
        "容量夹具须真实执行并保留原验拒绝事件，而不是伪造已付204次工作");
  }
  const auto seed = warm_cone_seed(fixture.reduced, fixture.options, fixture.start);
  auto result = warm_failure(fixture.reduced);
  const auto before = result;
  warm_state::Log log;
  log.enabled = true;
  warm_kernel::Limits limits;
  limits.max_iterations = 0;
  int checks = 0;
  const warm_kernel::Budget budget = [&] { ++checks; };
  {
    candidate::ScopedOracle oracle(&*fixture.oracle);
    require(!solver::v91_run_warm(seed.cone, seed.point, seed.tau, seed.kappa, fixture.options,
        fixture.start, result, log, limits, budget), "原oracle槽满必须有界退出");
  }
  require(std::string(log.status) == "oracle_limit" && !log.attempted && !log.accepted && checks == 0 &&
      log.kernel.stats.assessments_started == 0 && fixture.oracle->warm_event_count() == 204 &&
      fixture.stats.oracle.started == 204 && fixture.stats.oracle.completed == 204 && fixture.stats.oracle.rejected == 204 &&
      fixture.stats.oracle.errors == 0 && !fixture.oracle->terminal,
      "槽满不得创建第205个错误事件、启动kernel或补最后一次暖回调");
  same_non_timing(result, before);
  fixture.no_native_iterations();
  NativeOracleFixture terminal;
  terminal.oracle->terminal = candidate::OracleDecision::budget;
  const auto terminal_seed = warm_cone_seed(terminal.reduced, terminal.options, terminal.start);
  auto terminal_result = warm_failure(terminal.reduced);
  warm_state::Log unavailable;
  unavailable.enabled = true;
  {
    candidate::ScopedOracle oracle(&*terminal.oracle);
    require(!solver::v91_run_warm(terminal_seed.cone, terminal_seed.point, terminal_seed.tau, terminal_seed.kappa,
        terminal.options, terminal.start, terminal_result, unavailable, limits, budget), "已terminal的原oracle不得启动暖阶段");
  }
  require(std::string(unavailable.status) == "oracle_unavailable" && !unavailable.attempted &&
      terminal.stats.oracle.started == 0 && checks == 0, "preexisting terminal不能误作新失败事件或消耗额外槽位");
  ++budget_cases;
  details.push_back({"warm_oracle_capacity_stop", "budget"});
}

void check_warm_accept_abort() {
  Mode quiet(true);
  for (bool ordinary : {false, true}) {
    const auto original = coupled(true);
    const auto options = policy();
    const auto start = solver::Clock::now();
    candidate::Stats stats;
    SyntheticClock clock{start, stats};
    warm_state::Log log;
    log.enabled = true;
    bool injected = false;
    const auto result = candidate::control(original, options, start, stats,
        [&](const solver::Model& reduced, const solver::SolveOptions& child_options, solver::Clock::time_point child_start) {
          ++synthetic_core_calls;
          auto child = warm_failure(reduced);
          const auto seed = warm_cone_seed(reduced, child_options, child_start);
          warm_kernel::Limits limits;
          limits.max_iterations = 0;
          const warm_kernel::Budget budget = [&] {
            if (log.kernel.accepted) {
              injected = true;
              if (ordinary) throw std::runtime_error("原oracle接受后的暖owner普通异常");
              throw solver::BudgetExpired{};
            }
            solver::check_budget(child_options, child_start);
          };
          try {
            require(!solver::v91_run_warm(seed.cone, seed.point, seed.tau, seed.kappa, child_options,
                child_start, child, log, limits, budget), "未完成owner提交的暖阶段不能返回成功");
          } catch (const solver::BudgetExpired&) { child.status = "time_limit"; }
          return child;
        }, [&] { return clock(); });
    require(injected && log.kernel.accepted && !log.accepted &&
        std::string(log.status) == (ordinary ? "oracle_accept_aborted" : "budget_exception") &&
        stats.oracle.accepted == 1 && stats.oracle.candidate_event == 0 && !stats.oracle.selected_event &&
        stats.oracle.events.size() == 1 && std::string(stats.oracle.events.front().decision) == "accept" &&
        !stats.accepted && result.status == (ordinary ? "error" : "time_limit") &&
        std::string(stats.status) == (ordinary ? "native_error" : "time_limit"),
        "原oracle已接受后暖owner失败须保事件事实但安全关闭父提交，不能回退误接纳");
    cleared_quality(result);
    legacy_bait(result);
    timing_contract(result, stats, true);
    require(stats.child.completed == 1 && stats.timings.child_verification > 0,
        "安全关闭也须保child已付本地验收与全部legacy工作");
  }
  ++exception_cases;
  details.push_back({"warm_accept_abort_is_fail_closed", "exception"});
}

void check_warm_verification_accounting() {
  Mode quiet(true);
  for (bool optimal : {false, true}) {
    NativeOracleFixture fixture;
    const auto seed = warm_cone_seed(fixture.reduced, fixture.options, fixture.start, optimal);
    auto result = warm_failure(fixture.reduced);
    warm_state::Log log;
    log.enabled = true;
    solver::V91WarmAssessment assessment(seed.cone, fixture.options, fixture.start, result, log);
    const std::vector<double> old_x(2, 4.0 / 3.0), old_y(2, -1.0 / 3.0);
    auto old = solver::verify_lp_solution(fixture.reduced, old_x, old_y);
    require(candidate::commit_original_quality(assessment.trial, old_x, old_y, std::move(old), fixture.options),
        "计账夹具先放入旧最优trial，验证每次回调必须清除旧incumbent");
    auto x = seed.point.x, z = seed.point.z;
    for (double& value : x) value = static_cast<double>(static_cast<long double>(value) / seed.tau);
    for (double& value : z) value = static_cast<double>(static_cast<long double>(value) / seed.tau);
    bool valid = false;
    {
      candidate::ScopedOracle oracle(&*fixture.oracle);
      valid = assessment(0, x, z);
    }
    require(valid == optimal && assessment.pending == optimal && result.verification_seconds == assessment.trial.verification_seconds &&
        assessment.trial.verification_seconds >= 0 && log.seed_quality && log.last_quality &&
        log.seed_quality->numerically_optimal == optimal && log.last_quality->numerically_optimal == optimal &&
        fixture.stats.oracle.started == (optimal ? 1 : 0),
        "只累计trial已记录verify时间；当前local q未过不能借旧trial或重复原oracle咨询");
    require(result.status == "numerical_error" && !result.has_solution && !result.lp_optimality &&
        result.ipm_iterations == 137 && assessment.trial.ipm_iterations == 137,
        "回调完成不等于owner已提交，暖step0不可冒充新的HSD迭代标签");
    if (optimal) require(fixture.stats.timings.verification > 0 && fixture.stats.assessments.completed == 1,
        "原oracle自己的原验时间必须留在父账本，不能再累加到child本地verify");
    fixture.no_native_iterations();
  }
  ++transaction_cases;
  details.push_back({"warm_local_verification_counted_once", "transaction"});
}

void check_warm_not_reduced_and_scopes() {
  Mode quiet(true);
  const auto model = coupled();
  const auto options = policy();
  auto* previous = warm_state::active_state;
  {
    WarmMode enabled(true);
    warm_state::Report outer;
    require(outer.state.enabled && warm_state::active_state == &outer.state, "暖报告须由具名owner持有且保存TLS");
    original_quality(model, real_wrapper(model, options, true), 25.0 / 3.0);
    require(warm_state::active_state == &outer.state && !outer.state.attempted,
        "NotReduced公开入口使用自己的暖scope，不得串用外层日志");
    {
      WarmMode disabled(false);
      warm_state::Report inner;
      require(!inner.state.enabled && warm_state::active_state == &inner.state && std::string(inner.state.status) == "disabled",
          "暖关闭只隔离新阶段，不关闭父预处理pipeline");
      original_quality(model, real_wrapper(model, options, true), 25.0 / 3.0);
      require(warm_state::active_state == &inner.state && !inner.state.attempted, "关闭路径无暖kernel工作，返回仍恢复此前scope");
    }
    try { warm_state::Report inner; throw std::runtime_error("暖TLS组件异常"); }
    catch (const std::runtime_error&) {}
    require(warm_state::active_state == &outer.state, "暖报告异常析构必须恢复此前owner而非固定清空");
  }
  require(warm_state::active_state == previous, "所有暖报告结束后不得留下悬空TLS");
  const auto start = solver::Clock::now();
  const auto seed = warm_cone_seed(model, options, start);
  auto result = warm_failure(model);
  warm_state::Log log;
  log.enabled = true;
  warm_kernel::Limits limits;
  limits.max_iterations = 0;
  const warm_kernel::Budget budget = [&] { solver::check_budget(options, start); };
  {
    candidate::ScopedOracle none(nullptr);
    require(solver::v91_run_warm(seed.cone, seed.point, seed.tau, seed.kappa, options, start, result, log, limits, budget),
        "NotReduced无原生oracle时，本地assess已是原模型验收，可独立接纳");
  }
  original_quality(model, result, 25.0 / 3.0);
  require(log.accepted && log.kernel.stats.assessments_completed == 1 && result.ipm_iterations == 137,
      "原模型暖接纳仍只保原HSD标签，不添加原生恢复或伪造迭代");
  ++transaction_cases;
  details.push_back({"warm_not_reduced_and_disabled_scope", "transaction"});
}

}  // 匿名命名空间

int main() {
  try {
    check_off_wrapper();
    mapping("minimum_column_lower_offset", scalar(2, 1, 4, 7), 9, true);
    mapping("minimum_column_upper_offset", scalar(-2, -5, -2, -3), 1, true);
    mapping("maximum_column_upper_offset", scalar(3, -1, 4, 7, true), 19, true);
    auto model = scalar(3, -infinity, infinity, -4); row(model, 2, 4, infinity);
    mapping("minimum_original_row_lower", model, 2, true);
    model = scalar(2, -infinity, infinity, 7, true); row(model, 1, -infinity, 3);
    mapping("maximum_original_row_upper", model, 13, true);
    model = scalar(3, -5, 8); row(model, 1, 2, 5);
    mapping("ranged_row_lower", model, 6, true);
    model.sense = solver::ObjectiveSense::maximize;
    mapping("ranged_row_upper", model, 15, true);
    model = scalar(7, 3, 3, 11);
    model.costs.push_back(3); model.column_lower.push_back(-infinity); model.column_upper.push_back(infinity);
    model.kinds.push_back(solver::VariableKind::continuous); model.row_lower = {19}; model.row_upper = {19};
    model.column_start = {0, 1, 2}; model.row_index = {0, 0}; model.values = {5, 2};
    mapping("fixed_column_equality_offset", model, 38, true);
    mapping("minimum_real_reduced_child", coupled(true), 88.0 / 3.0, false);
    mapping("maximum_real_reduced_child", coupled(true, true), 104.0 / 3.0, false);
    check_not_reduced(); check_mip_bypass(); check_zero_budget(false); check_zero_budget(true);
    check_quality_transaction(); check_commit(true); check_commit(false);
    for (const auto kind : {ChildKind::good_nonoptimal, ChildKind::bad_dual, ChildKind::bad_primal,
                           ChildKind::no_candidate, ChildKind::bad_dimension}) synthetic_child(kind);
    check_presolve_status(); check_entry_deadline();
    check_late_boundary(true, false); check_late_boundary(false, false); check_late_boundary(false, true);
    check_child_exception(true); check_child_exception(false);
    for (const auto kind : {ProjectionKind::raw_pass, ProjectionKind::unchanged, ProjectionKind::dual_lower,
                           ProjectionKind::dual_upper, ProjectionKind::primal_lower, ProjectionKind::primal_upper,
                           ProjectionKind::both, ProjectionKind::breaks_row, ProjectionKind::breaks_gap,
                           ProjectionKind::nonfinite}) check_projection(kind);
    for (const auto boundary : {ProjectionBoundary::copy, ProjectionBoundary::primal, ProjectionBoundary::dual_after,
                               ProjectionBoundary::scan, ProjectionBoundary::trial_assessment, ProjectionBoundary::commit,
                               ProjectionBoundary::ordinary_then_expired}) check_projection_budget(boundary);
    check_projection_exception(false); check_projection_exception(true);
    check_old_incumbent_hook(); check_reject_then_accept_hook(); check_oracle_tls();
    check_owner_without_tail(); check_native_replay(); check_oracle_failure(false); check_oracle_failure(true);
    check_real_core_oracle_failure(false); check_real_core_oracle_failure(true);
    check_warm_reduced_original_oracle(); check_warm_oracle_capacity(); check_warm_accept_abort();
    check_warm_verification_accounting(); check_warm_not_reduced_and_scopes();
    require(details.size() == static_cast<std::size_t>(wrapper_cases + mapping_cases + transaction_cases +
        budget_cases + exception_cases) && component_ipm_calls > 0 && synthetic_core_calls > 0,
        "实际小例与合成边界计数必须守恒且不能冒称零全部求解");
    std::printf("{\"passed\":true,\"public_lp_runs\":0,\"explicit_highs_lp_solve_calls\":0,"
        "\"scope\":\"仅组件自测；component_ipm_calls计harness进入真实solve_ipm或v91_core的API次数(含零预算入口)，不含内部调用拦截；synthetic_core_calls另计，不是公开LP成绩\","
        "\"cases\":%zu,\"wrapper_cases\":%d,\"mapping_cases\":%d,\"transaction_cases\":%d,"
        "\"budget_cases\":%d,\"exception_cases\":%d,\"component_ipm_calls\":%d,\"synthetic_core_calls\":%d,\"details\":[",
        details.size(), wrapper_cases, mapping_cases, transaction_cases, budget_cases, exception_cases,
        component_ipm_calls, synthetic_core_calls);
    for (std::size_t i = 0; i < details.size(); ++i) {
      if (i) std::printf(",");
      std::printf("{\"id\":\"%s\",\"group\":\"%s\"}", details[i].id, details[i].group);
    }
    std::printf("]}\n");
    return 0;
  } catch (const std::exception& error) {
    std::fprintf(stderr, "组件自测失败（已完成%zu组，真实入口%d，合成入口%d）：%s\n",
        details.size(), component_ipm_calls, synthetic_core_calls, error.what());
    return 1;
  }
}

